select asset_type, status, count(*), min(dirty_from_date), max(dirty_from_date), max(updated_at), max(completed_at), sum((requested_generation<>completed_generation)::int) gen_lag, max(source_attempt_count) max_src_attempts from public."Feature04_Calculation_Queue" group by 1,2 order by 1,2;;
select asset_type, ticker, status, dirty_from_date, requested_generation, completed_generation, last_error_code, left(last_error,160) err, updated_at from public."Feature04_Calculation_Queue" where status<>'DONE' order by updated_at desc limit 20;;
select asset_type, status, calculation_version, count(*), count(distinct ticker), min(validated_through), max(validated_through), sum((not latest_value_available)::int) latest_unavailable, count(distinct feature_column) cols from public."Feature04_Column_Status" group by 1,2,3 order by 1,2;;
select null_reason, feature_column, count(*) from public."Feature04_Column_Status" where null_reason is not null group by 1,2 order by 3 desc limit 20;;
select asset_type, count(*) states, count(distinct ticker) tickers, min(checkpoint_date), max(checkpoint_date), string_agg(distinct state_version,',') sv, string_agg(distinct calculation_version,',') cv from public."Feature04_Calculation_State" group by 1;;
select n_per_ticker, count(*) from (select asset_type, ticker, count(*) n_per_ticker from public."Feature04_Calculation_State" group by 1,2) x group by 1 order by 1
